def sheet(cells: dict[str, str]) -> dict[str, int | str]:
    import re
    import sys

    if hasattr(sys, "set_int_max_str_digits"):
        sys.set_int_max_str_digits(0)

    total_length = sum(len(content) for content in cells.values())
    sys.setrecursionlimit(max(sys.getrecursionlimit(), 4 * total_length + 10000))

    token_pattern = re.compile(
        r"[A-Z][1-9][0-9]?|[A-Z]+|[0-9]+|<>|<=|>=|[+\-*/(),:=<>]"
    )

    values = {}
    visiting = set()

    def parse(content):
        tokens = token_pattern.findall(content)
        pos = 0

        def expression():
            nonlocal pos
            node = term()
            while pos < len(tokens) and tokens[pos] in ("+", "-"):
                op = tokens[pos]
                pos += 1
                node = (op, node, term())
            return node

        def term():
            nonlocal pos
            node = unary()
            while pos < len(tokens) and tokens[pos] in ("*", "/"):
                op = tokens[pos]
                pos += 1
                node = (op, node, unary())
            return node

        def unary():
            nonlocal pos
            if tokens[pos] == "-":
                pos += 1
                return ("neg", unary())
            return atom()

        def atom():
            nonlocal pos
            token = tokens[pos]
            pos += 1

            if token.isdigit():
                return ("number", int(token))

            if token == "(":
                node = expression()
                pos += 1  # )
                return node

            if token == "IF":
                pos += 1  # (
                left = expression()
                op = tokens[pos]
                pos += 1
                right = expression()
                pos += 1  # ,
                then = expression()
                pos += 1  # ,
                otherwise = expression()
                pos += 1  # )
                return ("if", op, left, right, then, otherwise)

            if token in ("SUM", "MIN", "MAX"):
                pos += 1  # (
                arguments = []
                while True:
                    if pos + 1 < len(tokens) and tokens[pos + 1] == ":":
                        start = tokens[pos]
                        end = tokens[pos + 2]
                        pos += 3
                        arguments.append(("range", start, end))
                    else:
                        arguments.append(expression())

                    if tokens[pos] == ")":
                        pos += 1
                        break
                    pos += 1  # ,
                return ("function", token, arguments)

            return ("cell", token)

        return expression()

    def evaluate_cell(name):
        if name not in cells:
            return 0
        if name in values:
            return values[name]
        if name in visiting:
            return "#CYCLE!"

        visiting.add(name)
        content = cells[name]
        if content.startswith("="):
            result = evaluate(parse(content[1:]))
        else:
            result = int(content)
        visiting.remove(name)
        values[name] = result
        return result

    def evaluate(node):
        kind = node[0]

        if kind == "number":
            return node[1]

        if kind == "cell":
            return evaluate_cell(node[1])

        if kind == "neg":
            value = evaluate(node[1])
            return value if isinstance(value, str) else -value

        if kind in ("+", "-", "*", "/"):
            left = evaluate(node[1])
            if isinstance(left, str):
                return left
            right = evaluate(node[2])
            if isinstance(right, str):
                return right

            if kind == "+":
                return left + right
            if kind == "-":
                return left - right
            if kind == "*":
                return left * right
            if right == 0:
                return "#DIV/0!"
            quotient = abs(left) // abs(right)
            return -quotient if (left < 0) != (right < 0) else quotient

        if kind == "if":
            op = node[1]
            left = evaluate(node[2])
            if isinstance(left, str):
                return left
            right = evaluate(node[3])
            if isinstance(right, str):
                return right

            if op == "=":
                condition = left == right
            elif op == "<>":
                condition = left != right
            elif op == "<":
                condition = left < right
            elif op == "<=":
                condition = left <= right
            elif op == ">":
                condition = left > right
            else:
                condition = left >= right
            return evaluate(node[4] if condition else node[5])

        function = node[1]
        aggregate = None

        def add(value):
            nonlocal aggregate
            if aggregate is None:
                aggregate = value
            elif function == "SUM":
                aggregate += value
            elif function == "MIN":
                aggregate = min(aggregate, value)
            else:
                aggregate = max(aggregate, value)

        for argument in node[2]:
            if argument[0] == "range":
                start, end = argument[1], argument[2]
                first_col = min(ord(start[0]), ord(end[0]))
                last_col = max(ord(start[0]), ord(end[0]))
                first_row = min(int(start[1:]), int(end[1:]))
                last_row = max(int(start[1:]), int(end[1:]))

                for row in range(first_row, last_row + 1):
                    for col in range(first_col, last_col + 1):
                        name = chr(col) + str(row)
                        if name in cells:
                            value = evaluate_cell(name)
                            if isinstance(value, str):
                                return value
                            add(value)
            else:
                value = evaluate(argument)
                if isinstance(value, str):
                    return value
                add(value)

        return 0 if aggregate is None else aggregate

    for name in cells:
        evaluate_cell(name)

    return {name: values[name] for name in cells}
